DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM public.oficina_tipos_de_grupo WHERE tipo IN ('post_img', 'carrusel_ig_v1', 'kit_historias') AND version = 4;
  IF n <> 3 THEN
    RAISE EXCEPTION 'se esperaban las 3 plantillas en version 4 y hay % (alguna no estaba en version 3)', n;
  END IF;
END $$;
